from collections import deque


def rate_limit(timestamps, limit, window):
    allowed = deque()
    result = []
    for t in timestamps:
        while allowed and allowed[0] <= t - window:
            allowed.popleft()
        if len(allowed) < limit:
            allowed.append(t)
            result.append(True)
        else:
            result.append(False)
    return result

